-- A class spell's school by its name on this client, as tooltips and macros
-- name it; the names are asked for at the first use.
local byName
function ns.spellSchool(name)
    if not byName then
        byName = {}
        for school, spells in pairs(SCHOOLS) do
            for spellID, english in pairs(spells) do byName[ns.Game.localSpellName(spellID, english)] = school end
        end
    end
    return name and byName[name]
end
